// Hand-written. Not generated by Speakeasy.
//
// Authlete answers a request for a service that does not exist with 403 and
// resultCode A458203, not 404. The generated code treats 404 as "gone" and
// everything else as an error, so a service deleted outside Terraform -- in
// the console, or by another configuration -- left the resource wedged:
//
//	Error: unexpected response from API. Got an unexpected response code 403
//
// Every plan failed there, and the only way out was `terraform state rm` by
// hand. Terraform's convention is that a resource missing from the API is
// planned for recreation instead.
//
// Matching on 403 alone would be wrong. A 403 can also mean the token is not
// allowed to see the service, and removing it from state then would plan a
// second service alongside one that still exists. A458203 is specific to the
// service not being there; both a deleted id and an id that never existed
// return it, and nothing else does.
//
// Clients are unaffected: a missing client returns a plain 404 (A001212),
// which the generated code already handles.
//
// The call sites are in generated files, so scripts/patch-missing-service.py
// reapplies them after regeneration and --check guards them in CI.
package provider

import (
	"bytes"
	"fmt"
	"net/http"
	"net/http/httputil"
)

// serviceNotFoundCode is the resultCode Authlete returns, inside a 403, when
// the service in the path does not exist.
const serviceNotFoundCode = "A458203"

// serviceIsGone reports whether a response says the service does not exist,
// as opposed to the caller not being allowed to see it.
func serviceIsGone(res *http.Response) bool {
	if res == nil || res.StatusCode != http.StatusForbidden {
		return false
	}
	// DumpResponse restores the body, so the caller can still dump it into a
	// diagnostic afterwards.
	dump, err := httputil.DumpResponse(res, true)
	if err != nil {
		return false
	}
	return bytes.Contains(dump, []byte(serviceNotFoundCode))
}

// serviceGoneMessage is the diagnostic a data source raises instead of
// reporting a bare 403. A data source cannot drop itself from state the way a
// resource can, since it was never in state; the right outcome is an error, so
// what matters here is that the error says what is wrong.
//
// The summary names the service, because a configuration that reads several
// has no other way to tell which one is missing.
func serviceGoneMessage(id string) (summary, detail string) {
	return fmt.Sprintf("Service %s does not exist", id),
		"Authlete reports no service with this id.\n\n" +
			"It may have been deleted, or the id may belong to another " +
			"organization or another cluster: a service id is unique to the " +
			"cluster that issued it, so one created on us.authlete.com is not " +
			"found on jp.authlete.com.\n\n" +
			"Check the id against the Management Console, and check that " +
			"server_url and AUTHLETE_SERVER_URL name the cluster the service " +
			"lives on."
}
